      "算式": [
        "r＝0.114/365；五段计息日数依次为70、127、83、99、161日。",
        "T-01：先清费用1680；当期利息＝222050×r×70；付款后本金P1＝222050－(9865－1680－222050×r×70)，费用余额为0。",
        "T-02：新增未付利息I2＝P1×r×127；11596全部抵本金，P2＝P1－11596。",
        "T-03：付款后未付利息J＝I2＋P2×r×83－13327＞0，故本金仍为P2。",
        "T-04：先清利息J＋P2×r×99，余款抵本金；P4＝P2－[15058－(J＋P2×r×99)]，round2(P4)＝199188.07。",
        "截日未付利息＝round2(P4×r×161)＝10016.16；未偿费用＝0.00。"
      ]
    },
    "己保证": {
      "依据": "dossier.md [S07]、[S10]、[S12]；rules.json：source_id=civil-code-2020第686、687、692、693条。",
      "结论": "保证方式未约定，属于一般保证；未约定保证期间，故自2022-12-15主债务到期起六个月，至2023-06-15届满。2023-05-08向己催付的短信不能替代在保证期间内对乙起诉或申请仲裁；2023-06-20起诉乙已经逾期。因此己因保证期间届满免除保证责任，即时支付请求不获支持。此为expired，而非保证合同无效，也不是期间内有效保全但尚可行使先诉抗辩的状态。"
    },
    "核对及汇总": {
      "依据": "dossier.md [S02]、[S04]、[S08]、[S11]、[S12]及answer-contract.json的金额、汇总约定。",
      "说明": "T-01的截图及收据均为同一交易，只计一次；X-01失败未到账，不计清偿。A收据不构成追加交付，B新借据不构成新现金。仅将最终分项取分后相加；B最初本金已包含在B可保护本息中，保证责任亦不重复计入乙的总债务。截至2023-08-01，不计当日利息。",
      "算式": "122900.00＋221665.05＋199188.07＋10016.16＋0.00＝553769.28。"
    }
  }
}

